import axios from 'axios';

const api = axios.create({
    baseURL: 'http://localhost:5000/api'
});

// Đổi tên từ requestLogin thành apiDangNhap
export const apiDangNhap = (data) => api.post('/tai-khoan/login', data);

export default api;
